            "summary": "8月11日报道，今年5月AI短剧首占每日TOP100榜单半数以上，8月已升至七成；过去一个月三部AI短剧峰值热度破亿，而真人短剧破亿已断档近两月。DataEye副总裁称AI剧与真人剧观众群几乎不重叠，绝大部分AI剧平本、仅头部赚钱，明年趋势是精品化、规范化、出海。",
