            "summary": "调查指AI漫剧主打极致低价引流（单集0.3–1元、前5–10集免费），但隐藏累计消费陷阱：一部260集剧全解锁累计可达76.5元。更普遍的是「付费前精品、付费后粗制」——后期量产PPT式漫单分钟成本仅几毛钱，前期引流动态漫单分钟200–500元。",
