            "impact": "对你：把「大任务拆小、多 AI 协作」当成方法论。比如一部 AI 漫剧=选题 AI+脚本 AI+分镜 AI+剪辑 AI，各管一段、互相校验，比一个 AI 闷头干更出片。"
