            "summary": "7月30日报道：百度萝卜快跑7月28日与Lyft旗下Freenow在伦敦启动公开道路测试，第六代无人车RT6首次进入英国，借当地平台快速落地；此前它已在中国香港拿到首张无安全员自动驾驶测试牌照。文章指出，百度选择「暂时让出入口、换取落地速度」。",
            "impact": "对行业：中国AI的出海路径正在从「卖技术」变成「借当地平台落地」。这个思路对内容创作者同样成立——想做海外，与其自己硬闯，不如先挂靠成熟平台跑通流程。当然那是后话，现阶段先把国内做扎实。"
